const caseStudies = {
 bememory: {
  goal:'매장이 늘어나도 안정적으로 운영할 수 있는 인프라',
  problems:[['분산된 운영 환경','여러 클라우드 서비스를 함께 사용하면서 유지보수가 복잡해졌습니다.'],['매장 확장에 따른 운영 한계','가맹점 확대에 대응할 서버 구조와 통합 모니터링 체계가 필요했습니다.']],
  solutions:[['서버 구조 전환','Lambda에서 EC2 기반 구조로 전환하고 AWS 인프라를 구축했습니다.'],['로그와 모니터링 통합','키오스크 로그 API를 개발하고 CloudWatch Insights와 Firehose를 활용해 로그 적재·모니터링 체계를 구축했습니다.']],
  insights:[['가맹점 확대에 따라 기존 서버 구조의 운영 한계가 드러났습니다.','EC2 기반 구조로 전환해 매장 확장에 대응할 인프라를 마련했습니다.'],['매장 이슈나 고객 요청에 대응할 통합 모니터링 체계가 부족했습니다.','로그 수집과 조회를 통합해 운영 상황을 확인할 수 있도록 구성했습니다.']]
 },
 cgv: {
  goal:'예매 트래픽이 몰려도 핵심 서비스는 안정적으로',
  problems:[['예매 오픈 시 트래픽 급증','예매 서비스의 부하가 앱·웹 전체에 영향을 주는 구조적 한계가 있었습니다.'],['서비스 확장의 유연성 부족','대규모 이벤트와 서비스 확장에 대응할 독립적인 운영 구조가 필요했습니다.']],
  solutions:[['MSA와 Amazon EKS','서비스를 분리하고 컨테이너 기반 환경에서 독립적으로 배포·확장할 수 있도록 설계했습니다.'],['Redis와 Kafka','Redis를 활용해 중복 예매와 DB 부하를 줄이고, Kafka 기반 비동기 요청 처리 구조를 구현했습니다.'],['멀티 리전 DR','장애 발생 시에도 서비스 연속성을 유지할 수 있도록 멀티 리전 DR 아키텍처를 구축했습니다.']],
  insights:[['예매 트래픽이 다른 서비스까지 영향을 주는 구조였습니다.','서비스를 분리해 장애 전파를 줄이고 독립적인 확장 기반을 마련했습니다.'],['장애 발생 시 예매 서비스의 연속성이 필요했습니다.','멀티 리전 DR 환경을 구축하고 복구 시나리오를 검증했습니다.']]
 },
 info: {
  goal:'재학생과 졸업생이 정보를 나누는 학과 커뮤니티',
  problems:[['학생 전용 소통 공간 부족','전공·진로 정보를 나누고 졸업생의 경험을 들을 수 있는 공간이 필요했습니다.'],['공강 시간에 사용할 공간 부족','시간대별로 비어 있는 강의실을 쉽게 확인할 수 있는 기능이 필요했습니다.']],
  solutions:[['게시판 API 개발','SNS 게시판의 생성·조회·수정·삭제 API를 개발하고 서비스를 배포했습니다.'],['빈 강의실 조회','공강 시간에 활용 가능한 강의실 정보를 제공하기 위해 시간대 기반 조회 로직을 설계했습니다.'],['졸업생 태그','졸업생 회원을 별도 태그로 구분해 재학생이 경험과 조언을 나눌 수 있도록 했습니다.']],
  insights:[['학내 정보와 경험을 나눌 소통 창구가 부족했습니다.','게시판과 졸업생 태그를 통해 재학생·졸업생 간 교류를 지원했습니다.'],['이용 가능한 강의실을 찾기 어려웠습니다.','시간대 기반 조회 기능으로 빈 강의실 정보를 제공했습니다.']]
 }
};
function caseImage(file,alt,caption=''){return `<figure class="case-figure"><a href="assets/${file}" target="_blank" rel="noopener" aria-label="${alt} 크게 보기"><img src="assets/${file}" alt="${alt}" loading="lazy" decoding="async"></a>${caption?`<figcaption>${caption}</figcaption>`:''}</figure>`}
function caseSection(num,title,body){return `<section class="case-section"><div class="case-heading"><span>${num}</span><h2>${title}</h2></div>${body}</section>`}
function renderCase(p){const c=caseStudies[p.id];const cards=(list)=>`<div class="case-cards">${list.map(([title,body],i)=>`<div class="case-card"><span class="case-num">0${i+1}</span><h3>${title}</h3><p>${body}</p></div>`).join('')}</div>`;
let evidence='';
if(p.id==='bememory') evidence=`<div class="evidence-grid"><div class="case-panel"><div class="eyebrow">SERVER MIGRATION</div><h3>Lambda → EC2</h3><p>K6 부하 테스트 · 7,500건 요청 처리 시 p95 응답시간</p><div class="comparison" role="img" aria-label="Lambda 65밀리초, EC2 t3.micro 25밀리초"><div class="bar-row"><span>Lambda</span><div class="bar-track"><i style="width:100%"></i></div><strong>65 ms</strong></div><div class="bar-row"><span>EC2 (t3.micro)</span><div class="bar-track"><i style="width:38.46%"></i></div><strong>25 ms</strong></div></div></div><div class="case-panel observability-panel"><div class="eyebrow">OBSERVABILITY</div><h3>로그 적재와 모니터링</h3><div class="service-group"><span>Firehose</span><span>Log stream</span><span>Insights</span><strong>CloudWatch</strong></div><p>키오스크 로그와 요청 현황을 확인할 수 있는 운영 관측 환경을 구성했습니다.</p><div class="observability-shots">${caseImage('monitoring.jpg','CloudWatch 요청 수와 응답시간 모니터링 화면','CloudWatch 대시보드')}${caseImage('kiosk-logs.jpg','키오스크 로그 조회 화면','키오스크 로그 조회')}</div></div></div>`;
if(p.id==='cgv') evidence=`<div class="case-panel"><div class="eyebrow">DISASTER RECOVERY</div><h3>멀티 리전으로 서비스 연속성 확보</h3><p>서울 리전 장애 상황에서도 도쿄 리전에서 서비스를 이어갈 수 있도록 Pilot Light 전략의 DR 환경을 구성했습니다.</p></div>${caseImage('dr.jpg','서울과 도쿄 리전의 DR 아키텍처','멀티 리전 DR · Pilot Light 전략')}<div class="case-panel"><div class="eyebrow">ASYNCHRONOUS PROCESSING</div><h3>중복 예매 방지와 비동기 처리</h3><p>Redis와 Kafka를 활용해 트래픽 급증 상황의 요청 처리 구조를 구성했습니다.</p><ol class="process-list"><li>예매 요청</li><li>Redis 기반 중복 제어</li><li>Kafka 비동기 처리</li><li>예약 데이터 반영</li></ol></div>${caseImage('async.jpg','Redis와 Kafka를 활용한 예매 처리 아키텍처','비동기 예매 처리 구성도')}`;
if(p.id==='info') evidence=`<div class="screen-grid">${[['sns-board.jpg','재학생 커뮤니티','게시판 CRUD API를 통해 정보를 작성하고 나누는 공간을 구현했습니다.'],['sns-room.jpg','빈 강의실 게시판','시간대별 강의실 사용 현황을 조회할 수 있도록 구성했습니다.'],['sns-alumni.jpg','졸업생 태그','졸업생을 구분해 재학생과의 소통을 돕습니다.']].map(([f,t,b])=>`<section><h3>${t}</h3><p>${b}</p>${caseImage(f,t+' 실제 서비스 화면')}</section>`).join('')}</div>`;
const insightExtra=p.id==='cgv'?`<div class="load-test-insight"><div class="load-test-copy"><div class="eyebrow">LOAD TEST RESULT</div><h3>1,000 TPS당 약 0.6&nbsp;vCPU</h3><p>부하 테스트 결과를 바탕으로 트래픽 1,000 TPS를 처리하는 데 필요한 CPU 리소스를 약 0.6 vCPU로 산정했습니다.</p><div class="load-metric" aria-label="1,000 TPS당 0.6 vCPU"><strong>1,000</strong><span>TPS</span><i>→</i><strong>0.6</strong><span>vCPU</span></div></div>${caseImage('load-test.jpg','CGV 부하 테스트 결과 원본 화면','부하 테스트 수행 결과')}</div>`:'';
return `<article class="detail case-study ${p.id}"><a class="back" href="#main">← main project</a><div class="eyebrow">${p.category}</div><h1>${p.name}</h1><p class="case-lead">${c.goal}</p><p class="detail-intro">${p.intro}</p><dl class="facts"><div><dt>PERIOD</dt><dd>${p.period}</dd></div><div><dt>ORGANIZATION</dt><dd>${p.org}</dd></div><div><dt>TEAM</dt><dd>${p.people}</dd></div></dl><div class="case-role"><h2>담당한 일</h2><ul>${p.tasks.map(t=>`<li>${t}</li>`).join('')}</ul></div><div class="stack-chips" aria-label="기술 스택">${p.stack.split(' · ').map(t=>`<span>${t}</span>`).join('')}</div>${caseSection('01','Problem',cards(c.problems))}${p.id!=='info'?caseSection('02','Architecture',(p.id==='bememory'?diagramViewer():caseImage(p.image,p.name+' 전체 아키텍처','구성도를 누르면 크게 볼 수 있습니다.'))):''}${caseSection(p.id==='info'?'02':'03','Solution',cards(c.solutions)+evidence)}${caseSection(p.id==='info'?'03':'04','Insight',`<div class="insight-list">${c.insights.map(([problem,solution])=>`<div class="insight-row"><div><span>PROBLEM</span><p>${problem}</p></div><span class="insight-arrow" aria-hidden="true">→</span><div><span>SOLUTION</span><p>${solution}</p></div></div>`).join('')}</div>${insightExtra}`)}${p.links.length?`<div class="links case-links">${p.links.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener">${n} ↗</a>`).join('')}</div>`:''}<a class="back case-end" href="#main">← 프로젝트 목록으로</a></article>`}

function diagramViewer(){return `<figure class="case-figure architecture-static"><a href="assets/bememory-architecture.png" target="_blank" rel="noopener" aria-label="비메모리 AWS 인프라 아키텍처 크게 보기"><img src="assets/bememory-architecture.png" alt="비메모리 AWS 인프라 아키텍처" loading="eager" decoding="async"></a><figcaption>구성도를 누르면 원본 크기로 볼 수 있습니다.</figcaption></figure>`}
